<script setup lang="ts">
import { zodiac,zodiacHour } from '~/utils/puzzles.mjs'
const {state,change,undo,reset,canUndo,saveError}=usePuzzleState('murder')
const suspects=[{id:'merchant',name:'Merchant',item:'abacus'},{id:'noble',name:'Noble / Courtier',item:'nobleHat'},{id:'gardener',name:'Gardener',item:'shears'}]
const names:Record<string,string>={comb:'Comb',abacus:'Mercantile Abacus',nobleHat:'Noble’s Hat',shears:'Gardening Shears',pufferfish:'Pufferfish',plumPit:'Plum Pit',monkshood:'Monkshood Flower',teaWhisk:'Tea Whisk',horse:'Horse Statuette',brush:'Calligraphy Brush',medallion:'Crest Medallion'}
const backgrounds:Record<string,string>={fish:'teaWhisk',mountains:'horse',bird:'brush'}
const candidates:Record<string,string[]>={emesis:['pufferfish','plumPit'],plant:['plumPit'],paralysis:['monkshood','pufferfish']}
const poison=computed(()=>state.value.poison || (state.value.symptom==='plant'?'plumPit':null))
const conflict=computed(()=>poison.value&&state.value.symptom&&!candidates[state.value.symptom].includes(poison.value))
const items=computed(()=>['comb',suspects.find(s=>s.id===state.value.suspect)?.item,conflict.value?null:poison.value,backgrounds[state.value.painting],'medallion'])
const hour=computed(()=>zodiacHour(state.value.hour,state.value.delay))
function set(field:string,value:any) { change({...state.value,[field]:value}) }
</script>
<template><div class="puzzle"><p>Use the witness, Death Records, Poison Compendium and painting background as separate clues.</p><div class="p-grid">
  <label>Witness names<select :value="state.suspect || ''" @change="set('suspect',($event.target as HTMLSelectElement).value)"><option value="">Choose accomplice</option><option v-for="s in suspects" :key="s.id" :value="s.id">{{ s.name }}</option></select></label>
  <label>Death Records · symptom<select :value="state.symptom || ''" @change="change({...state,symptom:($event.target as HTMLSelectElement).value,poison:null})"><option value="">Choose wording</option><option value="emesis">Signs of emesis / vomiting</option><option value="plant">Contaminated or noxious plant</option><option value="paralysis">Evidence of paralysis</option></select></label>
  <label>Poison confirmed by your documents<select :value="state.poison || ''" @change="set('poison',($event.target as HTMLSelectElement).value)"><option value="">{{ state.symptom==='plant'?'Plum Pit (from clue)':'Check the compendium' }}</option><option v-for="id in (state.symptom?candidates[state.symptom]:['pufferfish','plumPit','monkshood'])" :key="id" :value="id">{{ names[id] }}</option></select></label>
  <label>Death Records · hour of death<select :value="state.hour ?? ''" @change="set('hour',($event.target as HTMLSelectElement).value===''?null:Number(($event.target as HTMLSelectElement).value))"><option value="">Choose animal</option><option v-for="(name,i) in zodiac" :key="name" :value="i">{{ name==='Rabbit'?'Rabbit / Hare':name==='Pig'?'Pig / Boar':name }}</option></select></label>
  <label>Poison Compendium · hours to take effect<input type="number" min="1" max="12" :value="state.delay ?? ''" @input="set('delay',Number(($event.target as HTMLInputElement).value))"></label>
  <label>Fourth painting · background<select :value="state.painting || ''" @change="set('painting',($event.target as HTMLSelectElement).value)"><option value="">Choose background</option><option value="fish">Fish</option><option value="mountains">Mountains</option><option value="bird">Bird</option></select></label>
  </div><p v-if="state.symptom && candidates[state.symptom].length>1 && !poison" class="p-muted">This wording has more than one candidate. Use your other documents to confirm the poison; the accomplice does not choose it.</p><p v-if="conflict" class="p-error">The recorded poison conflicts with the symptom. Recheck both documents.</p><div class="p-result" aria-live="polite"><strong>Paintings · left → right</strong><ol class="p-sequence"><li v-for="(item,i) in items" :key="i"><small>Painting {{ i+1 }}</small><img v-if="item" :src="`/tools/kowakujo-murder/${item}.png`" alt="" width="48" height="48"><span>{{ item?names[item]:'More evidence needed' }}</span></li></ol><p><strong>Zodiac dial: {{ hour===null?'Record the hour and poison delay':zodiac[hour] }}</strong><span v-if="hour!==null"> · {{ state.delay }} positions anticlockwise from {{ zodiac[state.hour] }}.</span></p></div><details><summary>Where the clues come from</summary><p>Use a Ghostly Rifleman trap, get kills and speak to the separate ghost that appears. If no suspect is named, try another trap. Read time of death in the Death Records and the delay in the Poison Compendium. The fourth painting supplies the background clue only.</p></details><PuzzleActions :can-undo="canUndo" :save-error="saveError" @undo="undo" @reset="reset" /></div></template>
